import React, { useState, useEffect, useCallback } from 'react';
import axios from 'axios';

const API_BASE_URL = 'http://localhost:9091';

function AdminDashboard({ token,onLogout, setMessage }) {
  const [medicines, setMedicines] = useState([]);
  const [formData, setFormData] = useState({ id: null, name: '', description: '', price: '', stock: '' });
  const [isEditMode, setIsEditMode] = useState(false);

  // Fetch all medicines
  const fetchMedicines = useCallback(async () => {
    try {
      const response = await axios.get(`${API_BASE_URL}/api/admin/medicines`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setMedicines(response.data);
    } catch (error) {
      console.error('Error fetching medicines:', error);
      setMessage({ type: 'error', text: 'Failed to load medicines. Please check backend connection or token.' });
    }
  }, [token, setMessage]);

  useEffect(() => {
    fetchMedicines();
  }, [fetchMedicines]);

  // Handle form input
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  // Edit an existing medicine
  const handleEdit = (medicine) => {
    setFormData({
      id: medicine.id,
      name: medicine.name,
      description: medicine.description,
      price: medicine.price.toString(),
      stock: medicine.stock.toString(),
    });
    setIsEditMode(true);
  };

  // Clear form
  const handleClear = () => {
    setFormData({ id: null, name: '', description: '', price: '', stock: '' });
    setIsEditMode(false);
  };

  // Delete medicine
  const handleDelete = async (id) => {
    if (!window.confirm("Are you sure you want to delete this medicine?")) return;
    try {
      await axios.delete(`${API_BASE_URL}/api/admin/medicines/${id}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setMessage({ type: 'success', text: 'Medicine deleted successfully.' });
      fetchMedicines();
    } catch (error) {
      console.error('Delete error:', error);
      setMessage({ type: 'error', text: 'Failed to delete medicine.' });
    }
  };

  // Submit (Add / Update)
  const handleSubmit = async (e) => {
    e.preventDefault();
    const payload = {
      name: formData.name,
      description: formData.description,
      price: parseFloat(formData.price),
      stock: parseInt(formData.stock, 10),
    };

    try {
      if (isEditMode && formData.id) {
        // Update
        await axios.put(`${API_BASE_URL}/api/admin/medicines/${formData.id}`, payload, {
          headers: { Authorization: `Bearer ${token}` }
        });
        setMessage({ type: 'success', text: 'Medicine updated successfully.' });
      } else {
        // Add new
        await axios.post(`${API_BASE_URL}/api/admin/medicines`, payload, {
          headers: { Authorization: `Bearer ${token}` }
        });
        setMessage({ type: 'success', text: 'Medicine added successfully.' });
      }

      handleClear();
      fetchMedicines();
    } catch (error) {
      console.error('Save error:', error);
      setMessage({ type: 'error', text: 'Failed to save medicine.' });
    }
  };

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <h2 className="text-3xl font-bold text-indigo-700 mb-6">Admin Dashboard</h2>

      {/* Add/Edit Form */}
      <div className="bg-white p-6 rounded-xl shadow-md mb-8">
        <h3 className="text-xl font-semibold mb-4">{isEditMode ? 'Edit Medicine' : 'Add New Medicine'}</h3>
        <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-5 gap-4">
          <input
            type="text"
            name="name"
            placeholder="Name"
            required
            value={formData.name}
            onChange={handleChange}
            className="col-span-2 px-3 py-2 border rounded-lg"
          />
          <input
            type="number"
            name="price"
            placeholder="Price"
            required
            min="0.01"
            step="0.01"
            value={formData.price}
            onChange={handleChange}
            className="px-3 py-2 border rounded-lg"
          />
          <input
            type="number"
            name="stock"
            placeholder="Stock"
            required
            min="0"
            step="1"
            value={formData.stock}
            onChange={handleChange}
            className="px-3 py-2 border rounded-lg"
          />
          <div className="col-span-5 md:col-span-1 flex space-x-2">
            <button
              type="submit"
              className="flex-1 bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 transition"
            >
              {isEditMode ? 'Update' : 'Add'}
            </button>
            <button
              type="button"
              onClick={handleClear}
              className="bg-gray-500 text-white px-4 py-2 rounded-lg hover:bg-gray-600 transition"
            >
              Clear
            </button>
          </div>
          <textarea
            name="description"
            placeholder="Description"
            required
            value={formData.description}
            onChange={handleChange}
            className="col-span-5 px-3 py-2 border rounded-lg"
            rows="2"
          />
        </form>
      </div>

      {/* Medicines Table */}
      <div className="bg-white p-6 rounded-xl shadow-md overflow-x-auto">
        <h3 className="text-xl font-semibold mb-4">Current Medicines</h3>
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gray-50">
            <tr>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Name</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Price (₹)</th>
              <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">Stock</th>
              <th className="px-6 py-3 text-center text-xs font-medium text-gray-500 uppercase">Actions</th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-100">
            {medicines.map((med) => (
              <tr key={med.id} className="hover:bg-indigo-50 transition">
                <td className="px-6 py-4 font-medium text-gray-900">{med.name}</td>
                <td className="px-6 py-4 text-sm text-green-600">₹{med.price.toFixed(2)}</td>
                <td
                  className="px-6 py-4 text-right text-sm font-bold"
                  style={{ color: med.stock < 10 ? '#dc2626' : '#10b981' }}
                >
                  {med.stock}
                </td>
                <td className="px-6 py-4 text-center text-sm font-medium space-x-3">
                  <button onClick={() => handleEdit(med)} className="text-indigo-600 hover:text-indigo-900">
                    Edit
                  </button>
                  <button onClick={() => handleDelete(med.id)} className="text-red-600 hover:text-red-900">
                    Delete
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {medicines.length === 0 && <p className="text-center py-8 text-gray-500">No medicines found.</p>}
      </div>
    </div>
  );
}

export default AdminDashboard;
